<?php $page_title='Join FIBIN'; require_once 'includes/header.php';
if(is_logged_in()) redirect('dashboard.php');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';$base=preg_replace('/[^a-z0-9_]/','',strtolower(str_replace(' ','_',strtok($email,'@'))));$username=$base?:'user'.time();$role=$_POST['role']??'donor';if(!in_array($role,['donor','receiver']))$role='donor';if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<6){flash('error','Use a valid name, email and password of at least 6 characters.');}else{try{$s=$pdo->prepare("INSERT INTO users(name,username,email,password,role) VALUES(?,?,?,?,?)");$s->execute([$name,$username,$email,password_hash($password,PASSWORD_DEFAULT),$role]);flash('success','Account created. Please log in.');redirect('login.php');}catch(PDOException $e){flash('error','That email is already registered.');}}}
?>
<section class="auth-wrap"><div class="auth-brand"><img src="assets/images/fibin-logo.png" alt="FIBIN"><h1>Join the movement.</h1><p>Whether you have extra food or need support, there is a place for you at FIBIN.</p></div><div class="form-card auth-card"><h2>Create account</h2><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Full name<input name="name" required placeholder="Your name"></label><label>Email<input type="email" name="email" required placeholder="you@example.com"></label><label>I want to<select name="role"><option value="donor">Donate surplus food</option><option value="receiver">Request available food</option></select></label><label>Password<input type="password" name="password" minlength="6" required placeholder="Minimum 6 characters"></label><button class="btn primary full-btn">Create account →</button></form><p class="form-note">Already a member? <a href="login.php">Sign in</a></p></div></section>
